// phase-381 W4 — the C++ graph entry points must EXIST with these shapes, and
// the FFI symbols behind them must be DECLARED.
//
// Why this probe exists: on the C side in this same phase, the four repetitive
// entry points were generated by a Rust macro. They compiled, `just check-c`
// passed, and cbindgen emitted nothing for them — cbindgen does not expand
// macros, so the declarations were absent and the functions uncallable from C
// while every Rust-side signal stayed green. The C++ FFI header is generated
// the same way and carries the same trap, so it gets the same probe.
//
// Compile-only, taking METHOD POINTERS: there is no executor to call here, and
// the question is whether the surface exists with the right signatures.
//
// `-fno-exceptions -fno-rtti -std=c++14`, matching the embedded build (issue
// 0112): this header is compiled `-nostdinc++` against Zephyr's minimal libcpp,
// which is why the visitors are plain function pointers plus a `void *ctx` and
// not `std::function`.

#include <nros/executor.hpp>
#include <stddef.h>

namespace {

bool visit_node(void *ctx, const char *name, const char *ns, const char *enclave) {
    (void)ctx;
    (void)name;
    (void)ns;
    // nullptr is the contract's "this backend tracks no enclave" — a caller
    // must be able to test for it.
    return enclave == nullptr;
}

bool visit_names_and_types(void *ctx, const char *name, const char *const *types,
                           size_t types_count) {
    (void)ctx;
    (void)name;
    (void)types;
    // 0 is legal on a partially discovered graph.
    return types_count == types_count;
}

}  // namespace

int main() {
    using nros::Executor;
    using nros::Result;

    // Method pointers: a missing method, or one whose signature drifted, fails
    // to compile here rather than at a user's build.
    Result (Executor::*p_node_names)(nros_cpp_node_visit_fn, void *) = &Executor::get_node_names;
    Result (Executor::*p_topics)(nros_cpp_names_and_types_visit_fn, void *) =
        &Executor::get_topic_names_and_types;
    Result (Executor::*p_services)(nros_cpp_names_and_types_visit_fn, void *) =
        &Executor::get_service_names_and_types;
    Result (Executor::*p_count_pub)(const char *, size_t *) = &Executor::count_publishers;
    Result (Executor::*p_count_sub)(const char *, size_t *) = &Executor::count_subscribers;

    // And the visitor typedefs must accept conforming functions.
    nros_cpp_node_visit_fn nv = visit_node;
    nros_cpp_names_and_types_visit_fn ntv = visit_names_and_types;

    (void)p_node_names;
    (void)p_topics;
    (void)p_services;
    (void)p_count_pub;
    (void)p_count_sub;
    (void)nv;
    (void)ntv;
    return 0;
}
